// Payload dari backend TEREX. Di n8n webhook v2 body ada di .body,
// di versi lain langsung di root — tangani dua-duanya.
const d = $input.first().json.body || $input.first().json;

const emoji = {
  'Menunggu Approval': '\u23F3',
  'Disetujui': '\u2705',
  'Sedang Disiapkan': '\uD83D\uDCE6',
  'Dalam Pengiriman': '\uD83D\uDE9A',
  'Sampai (Delivered)': '\uD83C\uDF89',
  'Ditolak': '\u274C',
  'Dibatalkan': '\u26D4',
};
const e = emoji[d.status] || '\uD83D\uDCCB';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [
  `${e} <b>Delivery ${esc(d.deliveryId)}</b> \u2014 ${esc(d.status)}`,
  '',
  `Divisi: <b>${esc(d.customer)}</b>`,
  `Tujuan: ${esc(d.homebase)}${d.site ? ' \u00B7 ' + esc(d.site) : ''}`,
];
if (d.keperluan) lines.push(`Keperluan: ${esc(d.keperluan)}`);
if (d.itemCount) lines.push(`Item: ${esc(d.itemCount)}`);
lines.push(`Diminta oleh: ${esc(d.requester)}`);
if (d.actor && d.actor !== d.requester) lines.push(`Diproses oleh: ${esc(d.actor)}`);
if (d.note) lines.push(`Catatan: ${esc(d.note)}`);
lines.push('', 'https://terex-logistics.up.railway.app');

return [{ json: { message: lines.join('\n'), status: d.status, deliveryId: d.deliveryId } }];
